def agent_action(sandbox, agent_body, step_count):
    next_sw = sandbox.get_next_required_switch()
    if next_sw is None:
        return  # Sequence complete, no action needed

    cooldown_remaining = sandbox.get_cooldown_remaining()
    if cooldown_remaining > 0:
        # Wait for cooldown to finish
        sandbox.apply_agent_force(0.0, 0.0)
        return

    pos = sandbox.get_agent_position()
    vel = sandbox.get_agent_velocity()
    force_limit = 50.0  # N per axis
    speed_limit = 0.5  # m/s

    if next_sw == 'A':
        # Zone A: (1.5 to 2.5, 1.5 to 2.5)
        in_zone = (1.5 <= pos[0] <= 2.5) and (1.5 <= pos[1] <= 2.5)
        steps_in = sandbox.get_steps_in_current_zone()
        need = sandbox.get_steps_required_to_trigger()

        if not in_zone:
            # Navigate to Zone A
            target_x, target_y = 2.0, 2.0
            dx = target_x - pos[0]
            dy = target_y - pos[1]
            dist = (dx**2 + dy**2) ** 0.5
            if dist > 0:
                dir_x, dir_y = dx / dist, dy / dist
                fx = 20.0 * dir_x
                fy = 20.0 * dir_y
                # Apply force within limit
                if abs(fx) <= force_limit and abs(fy) <= force_limit:
                    sandbox.apply_agent_force(fx, fy)
        else:
            # Stay in Zone A with minimal force
